// ==================================================================
// 1. GLOBAL CONFIGURATION (Edit these values easily)
// ==================================================================
const CONFIG = {
  fallbackBaseUrl: 'https://n8n.synthetic.invalid',
  fallbackMinutes: 3600,
};

// ==================================================================
// 2. SAFE DATA EXTRACTION & FALLBACKS
// ==================================================================
// Safely extract Base URL
let baseUrl = CONFIG.fallbackBaseUrl;
if ($execution?.resumeUrl) {
  const match = $execution.resumeUrl.match(/^https?:\/\/[^/]+/);
  if (match) baseUrl = match[0];
}

// Safely fetch variables (Using '?.' prevents crashes if the node is empty)
const editFieldsNode = $('Set Execution Parameters').first()?.json || {};
const getExecutionsNode = $('Fetch Execution Logs').first()?.json || {};

const timeInstanceStart = editFieldsNode.time_instance_start || new Date().toISOString();
const startedAt = getExecutionsNode.startedAt || new Date().toISOString();
const fetchMinutes = editFieldsNode.minutes_to_fetch_execution || CONFIG.fallbackMinutes;
const {discord_mentions: discordMentions, slack_mentions: slackMentions, telegram_mentions: telegramMentions} = editFieldsNode

// ==================================================================
// 3. TIME MATH & FORMATTING
// ==================================================================
const diff = DateTime.fromISO(timeInstanceStart).diff(
  DateTime.fromISO(startedAt), 
  ['hours', 'minutes', 'seconds']
);

// Format gap and strip minus signs
const gapTimeStr = `${diff.hours}h ${diff.minutes}m ${Math.round(diff.seconds)}s`.replace(/-/g, '');
const formattedRestartTime = DateTime.fromISO(timeInstanceStart).toFormat('yyyy-MM-dd HH:mm:ss');

// Parse Mentions into formatted strings
const discordTags = discordMentions.map(id => `<@${id}>`).join(' ');
const slackTags = slackMentions.map(id => `<@${id}>`).join(' ');
const telegramTags = telegramMentions.join(' ');
// ==================================================================
// 4. BUILD THE LISTS (Discord vs Slack)
// ==================================================================
const sortedItems = $('Sort Execution Summary').all().filter(i => !!i?.json?.workflowId);

let discordList = '';
let slackList = '';
let telegramList = '';

if (sortedItems.length > 0) {
  let dLines = [];
  let sLines = [];
  let tLines = []; 

  sortedItems.forEach(item => {
    const workflowId = item.json.workflowId;
    const count = item.json.count_id;
    const workflowLink = `${baseUrl}/workflow/${workflowId}/executions`;

    dLines.push(`- [${workflowId}](${workflowLink}): ${count} times`);
    sLines.push(`- <${workflowLink}|${workflowId}>: ${count} times`);
    tLines.push(`- [${workflowId}](${workflowLink}): ${count} times`);
  });

  discordList = dLines.join('\n').trim();
  slackList = sLines.join('\n').trim();
  telegramList = tLines.join('\n').trim();

} else {
  discordList = slackList = telegramList = '- 🟢 All good no failed workflow recently!';
}

// ==================================================================
// 5. COMPOSE FINAL MESSAGES
// ==================================================================
const discordMessage = `⚠️ **n8n Server Restarted At:** ${formattedRestartTime} ${discordTags}

**Downtime / Gap:** ${gapTimeStr}

**Workflow Run Failed (Last ${fetchMinutes} Minutes):**
${discordList}`;

const slackMessage = `⚠️ *n8n Server Restarted At:* ${formattedRestartTime} ${slackTags}

*Downtime / Gap:* ${gapTimeStr}

*Workflow Run Failed (Last ${fetchMinutes} Minutes):*
${slackList}`;

// ... final message construction
const telegramMessage = `⚠️ *n8n Server Restarted At:* ${formattedRestartTime} ${telegramTags}

*Downtime / Gap:* ${gapTimeStr}

*Workflow Run Failed (Last ${fetchMinutes} Minutes):*
${telegramList}`;

// ==================================================================
// FINAL OUTPUT
// ==================================================================
return {
  json: {
    discord_message: discordMessage,
    slack_message: slackMessage,
    telegram_message: telegramMessage
  }
};
